import{_ as a,o as i,c as t,a2 as d}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lista de Sugerencias de Configuración Ampliada","description":"","frontmatter":{},"headers":[],"relativePath":"es/98-扩展设定建议清单.md","filePath":"es/98-扩展设定建议清单.md","lastUpdated":1789183869000}'),o={name:"es/98-扩展设定建议清单.md"};function s(n,e,c,l,r,u){return i(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="lista-de-sugerencias-de-configuracion-ampliada" tabindex="-1">Lista de Sugerencias de Configuración Ampliada <a class="header-anchor" href="#lista-de-sugerencias-de-configuracion-ampliada" aria-label="Permalink to &quot;Lista de Sugerencias de Configuración Ampliada&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>98</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>configuración ampliada, sugerencias de creación, direcciones de configuración, apertura, campos por desarrollar</td></tr></tbody></table><h2 id="i-notas" tabindex="-1">I. Notas <a class="header-anchor" href="#i-notas" aria-label="Permalink to &quot;I. Notas&quot;">​</a></h2><p>Este documento enumera las direcciones y sugerencias disponibles para la creación ampliada en el sistema de configuración de la Civilización Simbiótica del Ancla, con el objetivo de proporcionar inspiración y orientación a los creadores de configuración y ayudarles a realizar ampliaciones valiosas dentro del marco existente. Esta lista está clasificada por módulos; cada dirección de ampliación incluye una descripción de la dirección, el valor de la ampliación, la relación con la configuración existente y sugerencias de creación. Cabe destacar que esta lista es solo de carácter consultivo; los creadores pueden dar rienda suelta a su creatividad siempre que mantengan la coherencia de la configuración, y también pueden desarrollar direcciones completamente nuevas no cubiertas por esta lista. Todas las configuraciones ampliadas deben superar la comprobación de la Lista de Autoverificación de Contradicciones de Configuración (documento 97) antes de incorporarse formalmente.</p><h2 id="ii-direcciones-de-ampliacion-de-la-cosmovision-y-la-configuracion-central" tabindex="-1">II. Direcciones de ampliación de la cosmovisión y la configuración central <a class="header-anchor" href="#ii-direcciones-de-ampliacion-de-la-cosmovision-y-la-configuracion-central" aria-label="Permalink to &quot;II. Direcciones de ampliación de la cosmovisión y la configuración central&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E01</td><td>Existencia más allá de los límites del universo</td><td>Explorar si existen otros universos o existencias de dimensión superior más allá de la red de leyes del Universo Hengyuan, proporcionando una cosmología más grandiosa a la configuración</td><td>Documentos 00, 28</td><td>Puede establecerse la existencia de un «muro cósmico», así como las historias de los escasísimos exploradores que lo atraviesan, sentando las bases para una futura interacción interuniversal</td></tr><tr><td>E02</td><td>La esencia de la voluntad cósmica</td><td>Explorar en profundidad si existe alguna «voluntad cósmica» en el fondo de la red de leyes, y su relación con el mecanismo del Ancla</td><td>Documentos 00, 20</td><td>La voluntad cósmica puede establecerse como un fenómeno de autoorganización no personificado de las leyes, y no como una deidad concreta, manteniendo la postura de «La Realidad como Fundamento»</td></tr><tr><td>E03</td><td>Civilizaciones perdidas de la era pre-Ancla</td><td>Definir en detalle las civilizaciones otrora brillantes pero ya extintas de la era pre-Ancla, enriqueciendo la profundidad histórica</td><td>Documentos 71, 93</td><td>Pueden establecerse de tres a cinco civilizaciones perdidas representativas, cada una con su sistema de cultivo, cultura y causa de extinción únicos, proporcionando material para la configuración arqueológica</td></tr><tr><td>E04</td><td>Escuelas filosóficas del concepto de simbiosis</td><td>En el gran marco de «contra la depredación, por la simbiosis», establecer las distintas interpretaciones del concepto de simbiosis por las diferentes escuelas filosóficas</td><td>Documentos 04, 03</td><td>Pueden establecerse escuelas como la «escuela simbiótica radical», la «escuela simbiótica moderada», la «escuela simbiótica ecológica» y la «escuela simbiótica tecnológica»; sus confrontaciones de pensamiento pueden convertirse en una importante tensión narrativa</td></tr></tbody></table><h2 id="iii-direcciones-de-ampliacion-del-sistema-de-cultivo" tabindex="-1">III. Direcciones de ampliación del sistema de cultivo <a class="header-anchor" href="#iii-direcciones-de-ampliacion-del-sistema-de-cultivo" aria-label="Permalink to &quot;III. Direcciones de ampliación del sistema de cultivo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E05</td><td>Métodos detallados de un solo sistema</td><td>Desarrollar en detalle uno de los Trescientos Sistemas, incluidos los métodos concretos de cultivo, los métodos de ruptura de etapa y los errores comunes</td><td>Documentos 10–19, 91</td><td>Se sugiere priorizar las Tres Bases de Origen y los sistemas de la categoría de ingeniería aplicada estrechamente vinculados a la tecnología; el documento detallado de cada sistema puede incluir pasos de cultivo, fórmulas mentales, requisitos de recursos y advertencias de riesgo</td></tr><tr><td>E06</td><td>Esquemas de combinación de cultivo simultáneo</td><td>Estudiar la compatibilidad del cultivo simultáneo entre distintos sistemas y diseñar esquemas óptimos de combinación multisistema</td><td>Documentos 10, 11–13</td><td>Pueden establecerse «combinaciones de oro» (como Iteración Deductiva + Principios Legales Espaciales + Ingeniería Aplicada) y diversas combinaciones poco convencionales, analizando las ventajas y limitaciones de cada una</td></tr><tr><td>E07</td><td>Cuellos de botella del cultivo y métodos de ruptura</td><td>Definir en detalle los cuellos de botella que cada sistema puede encontrar en las distintas etapas, y los múltiples métodos para superarlos</td><td>Documentos 14, 19</td><td>Pueden establecerse distintos tipos de cuellos de botella como la «tribulación del demonio interior», la «barrera de leyes» y el «obstáculo de origen», con las vías de ruptura correspondientes, añadiendo profundidad al proceso de cultivo</td></tr><tr><td>E08</td><td>Constituciones especiales y adaptación a los sistemas</td><td>Definir diversas constituciones especiales (como el cuerpo Dao innato, el cuerpo de afinidad elemental y el sensor de conciencia potente) y sus relaciones de adaptación con los distintos sistemas de cultivo</td><td>Documentos 12, 51</td><td>Puede diseñarse una «matriz de adaptación constitución–sistema» que ayude a los creadores a determinar rápidamente qué sistemas son adecuados para cultivar con una constitución determinada</td></tr><tr><td>E09</td><td>Clasificación detallada de los recursos de cultivo</td><td>Clasificar y definir en detalle los diversos recursos necesarios para el cultivo (materiales celestiales y tesoros terrenales, cristales de energía, fragmentos de leyes, etc.)</td><td>Documentos 18, 65</td><td>Pueden establecerse el grado, el lugar de origen, el método de recolección, el método de conservación y las prohibiciones de uso de los recursos, construyendo una ecología completa de los recursos de cultivo</td></tr></tbody></table><h2 id="iv-direcciones-de-ampliacion-del-sistema-social" tabindex="-1">IV. Direcciones de ampliación del sistema social <a class="header-anchor" href="#iv-direcciones-de-ampliacion-del-sistema-social" aria-label="Permalink to &quot;IV. Direcciones de ampliación del sistema social&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E10</td><td>Formas sociales concretas de los Cinco Tipos</td><td>Desarrollar en detalle los sistemas sociales, los modelos económicos y las características culturales específicos de cada uno de los Cinco Tipos de Civilización Simbiótica</td><td>Documentos 30–35</td><td>Cada tipo puede tener su forma urbana típica, estructura familiar, modelo educativo y festividades, haciendo que los Cinco Tipos sean cada uno distintivo</td></tr><tr><td>E11</td><td>Planificación y construcción de las ciudades simbióticas</td><td>Definir los conceptos de planificación, los estilos arquitectónicos, las infraestructuras y la zonificación funcional de las ciudades de la civilización simbiótica</td><td>Documentos 39, 60</td><td>Pueden diseñarse distintos tipos de formas urbanas como la «ciudad simbiótica vertical», la «ciudad de anidamiento ecológico» y la «ciudad de plegado espacial»</td></tr><tr><td>E12</td><td>Funcionamiento detallado del sistema educativo</td><td>Definir en detalle el mecanismo completo de funcionamiento del sistema educativo simbiótico, desde la educación preescolar hasta la educación superior y la educación de cultivo</td><td>Documentos 37, 43</td><td>Pueden establecerse el sistema curricular, los métodos de evaluación, el sistema de mentores y los planes educativos interraciales</td></tr><tr><td>E13</td><td>Funcionamiento detallado del sistema médico</td><td>Definir en detalle el mecanismo de funcionamiento del sistema médico simbiótico, incluida la combinación de la medicina convencional y la medicina de cultivo</td><td>Documentos 38, 44</td><td>Pueden establecerse el sistema hospitalario, los procedimientos de reembolso del seguro médico, las normas especiales del tratamiento de cultivo y los planes médicos interraciales</td></tr><tr><td>E14</td><td>Sistema de seguridad social y bienestar</td><td>Definir en detalle el sistema de seguridad social de la civilización simbiótica, incluidos la jubilación, el desempleo y la asistencia</td><td>Documentos 32, 08</td><td>Pueden establecerse las condiciones de solicitud, los estándares de pago, las fuentes de financiación y los mecanismos de supervisión de las prestaciones</td></tr></tbody></table><h2 id="v-direcciones-de-ampliacion-del-derecho-y-la-gobernanza" tabindex="-1">V. Direcciones de ampliación del derecho y la gobernanza <a class="header-anchor" href="#v-direcciones-de-ampliacion-del-derecho-y-la-gobernanza" aria-label="Permalink to &quot;V. Direcciones de ampliación del derecho y la gobernanza&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E15</td><td>Casos jurídicos típicos</td><td>Redactar casos típicos juzgados por el Tribunal Simbiótico, mostrando la aplicación del derecho en la práctica</td><td>Documentos 40–49, 92</td><td>Pueden redactarse casos representativos como el «caso de monopolio de recursos de cultivo», el «caso de indemnización por contaminación transplanar» y el «caso de derechos de las Entidades Oscuras de Reemplazo»</td></tr><tr><td>E16</td><td>Sistema de autonomía local</td><td>Definir en detalle los sistemas de autonomía y la división de competencias de cada región estelar y cada plano dentro del marco constitucional</td><td>Documentos 40, 49</td><td>Pueden establecerse los modelos de autonomía de las distintas unidades autónomas, sus relaciones con el gobierno central y los procedimientos de elaboración de los reglamentos de autonomía</td></tr><tr><td>E17</td><td>Sistemas electoral y democrático</td><td>Definir en detalle el sistema electoral de los representantes de la Asamblea Legislativa del Ancla y el mecanismo de decisión democrática</td><td>Documentos 32, 49</td><td>Pueden establecerse la división de circunscripciones, las cualificaciones de los candidatos, los procedimientos electorales, los modos de votación y los sistemas de mandato</td></tr><tr><td>E18</td><td>Mecanismo de aplicación de la ley</td><td>Definir en detalle el mecanismo de aplicación de la ley, incluidos los órganos de ejecución, los procedimientos de ejecución y las medidas coercitivas</td><td>Documentos 48, 49</td><td>Pueden establecerse la estructura organizativa, las facultades de ejecución, los procedimientos de ejecución y los mecanismos de supervisión de los órganos de ejecución</td></tr></tbody></table><h2 id="vi-direcciones-de-ampliacion-de-la-vida-y-las-razas" tabindex="-1">VI. Direcciones de ampliación de la vida y las razas <a class="header-anchor" href="#vi-direcciones-de-ampliacion-de-la-vida-y-las-razas" aria-label="Permalink to &quot;VI. Direcciones de ampliación de la vida y las razas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E19</td><td>Configuración detallada de una sola raza</td><td>Desarrollar en detalle una raza del Registro de las Diez Mil Razas, incluidas las características fisiológicas, la estructura social, las tradiciones culturales y la evolución histórica</td><td>Documentos 50–52, 94</td><td>Se sugiere priorizar razas distintivas como la Raza Dragón (Lóng Zú), la Raza Elfo (Jīnglíng Zú), la Raza Máquina (Jīxiè Zú) y la Raza Cuerpo de Conciencia (Yìshítǐ Zú); cada raza puede incluir lengua, religión, arte y costumbres</td></tr><tr><td>E20</td><td>Casos concretos de Vida Anómala</td><td>Definir individuos o grupos concretos de Vida Anómala, mostrando la aplicación práctica de los tres tipos de procedimientos de tratamiento</td><td>Documentos 53–54</td><td>Pueden establecerse casos como los «vagabundos del vacío», la «vida de fragmentos temporales» y los «parásitos de leyes»</td></tr><tr><td>E21</td><td>Tipos concretos de Energía Anómala</td><td>Definir en detalle las características, fuentes, usos y métodos de control de las diversas Energías Anómalas</td><td>Documentos 55–56</td><td>Pueden establecerse tipos como la «energía causal», la «energía de conciencia» y la «energía de eco temporal»</td></tr><tr><td>E22</td><td>Casos concretos de Entidades Oscuras de Reemplazo</td><td>Definir historias individuales concretas de Entidades Oscuras de Reemplazo, mostrando la aplicación práctica de las Directrices Éticas del Alma Dual y del tratamiento de las cuatro ramas</td><td>Documentos 57–59</td><td>Pueden redactarse historias de casos de diferentes tipos de Entidades Oscuras de Reemplazo, explorando los dilemas éticos de la coexistencia de dos almas</td></tr><tr><td>E23</td><td>Descendientes de la integración interracial</td><td>Definir las características y la cultura de las razas mixtas nacidas de matrimonios entre diferentes razas</td><td>Documentos 52, 77</td><td>Pueden establecerse razas mixtas como los «medios elfos», los «hombres dragón» y los «humanos biónicos mecánicos», explorando su identidad y su fusión cultural</td></tr></tbody></table><h2 id="vii-direcciones-de-ampliacion-de-la-tecnologia-y-la-energia" tabindex="-1">VII. Direcciones de ampliación de la tecnología y la energía <a class="header-anchor" href="#vii-direcciones-de-ampliacion-de-la-tecnologia-y-la-energia" aria-label="Permalink to &quot;VII. Direcciones de ampliación de la tecnología y la energía&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E24</td><td>Principios detallados de una sola tecnología</td><td>Proporcionar un análisis detallado de los principios de una tecnología clave (como el Espejo de Réplica, el espacio aislado y la ingenierización del Fruto Multiplicador)</td><td>Documentos 60–69, 63–64</td><td>Pueden establecerse la historia de desarrollo, los componentes centrales, el flujo de trabajo, las limitaciones técnicas y las direcciones de mejora de la tecnología</td></tr><tr><td>E25</td><td>Clasificación detallada de los equipos de cultivo</td><td>Definir la clasificación, funciones, niveles y métodos de uso de los diversos equipos auxiliares de cultivo</td><td>Documentos 61, 67</td><td>Pueden establecerse tipos de equipos como la «cápsula de cultivo», el «detector de leyes», el «convertidor de energía» y el «amplificador de conciencia»</td></tr><tr><td>E26</td><td>Configuración detallada del hardware del Ancla</td><td>Definir en detalle la estructura, funciones, construcción y mantenimiento de las instalaciones de hardware del Ancla</td><td>Documentos 20, 67</td><td>Pueden establecerse los componentes centrales, el suministro de energía, el ciclo de mantenimiento y el manejo de averías de los Anclas artificiales</td></tr><tr><td>E27</td><td>Tecnología de comunicación transplanar</td><td>Definir en detalle los principios técnicos, los tipos de equipos, los protocolos de comunicación y los mecanismos de seguridad de la comunicación transplanar</td><td>Documentos 66, 81</td><td>Pueden establecerse distintos métodos de comunicación como la «comunicación por ondas de Ancla», la «comunicación por plegado espacial» y la «comunicación por resonancia de conciencia»</td></tr></tbody></table><h2 id="viii-direcciones-de-ampliacion-de-la-historia-y-los-acontecimientos" tabindex="-1">VIII. Direcciones de ampliación de la historia y los acontecimientos <a class="header-anchor" href="#viii-direcciones-de-ampliacion-de-la-historia-y-los-acontecimientos" aria-label="Permalink to &quot;VIII. Direcciones de ampliación de la historia y los acontecimientos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E28</td><td>Relatos detallados de los grandes acontecimientos históricos</td><td>Proporcionar relatos históricos detallados de un gran acontecimiento de la cronología</td><td>Documentos 70–79, 93</td><td>Puede narrarse en detalle el proceso completo de acontecimientos como el «acontecimiento de apertura de los Trescientos Sistemas», la «implementación de la Estrategia de Activación del 20 %» y el «primer hito de la ascensión»</td></tr><tr><td>E29</td><td>Biografías de figuras históricas</td><td>Redactar biografías detalladas de las figuras clave, enriqueciendo la profundidad humanística de la historia</td><td>Documento 95</td><td>Pueden redactarse biografías de figuras clave como «Xuánhéng Zǐ», «Gòngshēng Zǐ», «Lìxiàn Gōng» y «Sānbǎi Shī»</td></tr><tr><td>E30</td><td>Análisis hipotético de los puntos de inflexión históricos</td><td>Analizar cómo habría sido diferente el desarrollo de la civilización simbiótica si un determinado acontecimiento histórico hubiera tomado otro rumbo</td><td>Documentos 70–79</td><td>Pueden realizarse análisis hipotéticos como «si la Constitución Simbiótica no se hubiera aprobado» y «si la Estrategia de Activación del 20 % hubiera fracasado», mostrando la contingencia de la historia</td></tr><tr><td>E31</td><td>Registros detallados de los hallazgos arqueológicos</td><td>Definir los hallazgos detallados y los resultados de investigación de una determinada arqueología transplanar</td><td>Documentos 84–87</td><td>Pueden establecerse «el hallazgo arqueológico de una determinada civilización perdida» y «los resultados de la arqueología por regresión temporal de un determinado nodo histórico clave»</td></tr></tbody></table><h2 id="ix-direcciones-de-ampliacion-transplanar-y-temporal" tabindex="-1">IX. Direcciones de ampliación transplanar y temporal <a class="header-anchor" href="#ix-direcciones-de-ampliacion-transplanar-y-temporal" aria-label="Permalink to &quot;IX. Direcciones de ampliación transplanar y temporal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Número</th><th>Dirección de ampliación</th><th>Valor de la ampliación</th><th>Configuración relacionada</th><th>Sugerencias de creación</th></tr></thead><tbody><tr><td>E32</td><td>Configuración detallada de planos específicos</td><td>Definir los parámetros de leyes, las formas de civilización, los entornos geográficos y las historias de un plano específico</td><td>Documentos 80, 81</td><td>Pueden establecerse distintos tipos de planos específicos como el «plano de alta magia», el «plano tecnológico», el «plano salvaje» y el «plano de conciencia»</td></tr><tr><td>E33</td><td>Casos de diplomacia transplanar</td><td>Definir casos concretos del establecimiento de relaciones diplomáticas entre la civilización simbiótica y otras civilizaciones de otros planos</td><td>Documentos 81, 88</td><td>Pueden establecerse acontecimientos diplomáticos concretos como el primer contacto, las negociaciones de establecimiento de relaciones, el intercambio cultural y los acuerdos comerciales</td></tr><tr><td>E34</td><td>Casos concretos de regresión temporal</td><td>Definir el proceso concreto, los hallazgos y los impactos de una determinada operación de regresión temporal</td><td>Documentos 82–83, 89</td><td>Pueden establecerse casos como «la resolución mediante regresión de un determinado misterio histórico» y «la restauración mediante regresión de una determinada civilización extinta»</td></tr><tr><td>E35</td><td>Registros detallados de acontecimientos de paradojas temporales</td><td>Definir el proceso completo de un determinado acontecimiento de paradoja temporal, incluidos su ocurrencia, la respuesta de emergencia y la reparación causal</td><td>Documento 89</td><td>Puede redactarse un registro completo de tratamiento de un acontecimiento de paradoja a pequeña escala, mostrando el funcionamiento práctico de los mecanismos de prevención y control</td></tr><tr><td>E36</td><td>Conflictos transplanar y su resolución</td><td>Definir los conflictos entre la civilización simbiótica y otras civilizaciones de otros planos y el proceso de resolución pacífica</td><td>Documentos 81, 88</td><td>Pueden establecerse distintos tipos de casos de conflictos transplanar como disputas por recursos, conflictos culturales y litigios fronterizos</td></tr></tbody></table><h2 id="x-principios-de-creacion-de-la-configuracion-ampliada" tabindex="-1">X. Principios de creación de la configuración ampliada <a class="header-anchor" href="#x-principios-de-creacion-de-la-configuracion-ampliada" aria-label="Permalink to &quot;X. Principios de creación de la configuración ampliada&quot;">​</a></h2><p>Al crear configuraciones ampliadas, deben seguirse los siguientes principios:</p><ol><li><strong>Coherencia primero</strong>: todas las configuraciones ampliadas deben permanecer lógicamente coherentes con la configuración existente y superar la comprobación de la Lista de Autoverificación de Contradicciones de Configuración.</li><li><strong>La Realidad como Fundamento</strong>: las configuraciones ampliadas deben deducirse razonablemente sobre la base de las leyes objetivas, evitando la pura especulación y el colapso de la configuración.</li><li><strong>Postura simbiótica</strong>: las configuraciones ampliadas deben mantener siempre la postura central de oponerse a la depredación y defender la simbiosis, y no deben defender comportamientos depredadores.</li><li><strong>Apertura</strong>: las configuraciones ampliadas deben conservar un cierto grado de apertura, dejando espacio para futuras ampliaciones.</li><li><strong>Utilidad práctica</strong>: las configuraciones ampliadas deben tener un valor creativo práctico, proporcionando material útil para la creación de historias, el diseño de juegos y la discusión teórica.</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Lista de Sugerencias de Configuración Ampliada es la «puerta abierta» del sistema de configuración de la Civilización Simbiótica del Ancla. Muestra que este sistema de configuración no es un producto cerrado y acabado, sino un sistema vivo que crece y se enriquece continuamente. Las treinta y seis direcciones de ampliación son solo un punto de partida; la verdadera creatividad de la configuración proviene de la imaginación y el entusiasmo de cada participante. Mientras se respete el principio básico de la coherencia de la configuración, cada ampliación valiosa se convertirá en un componente indispensable de la gran narrativa de la Civilización Simbiótica del Ancla.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>97-设定矛盾自查表 (Lista de Autoverificación de Contradicciones de Configuración)</li><li>99-文档版本与维护说明 (Versión de Documentos y Notas de Mantenimiento)</li><li>96-常见问题FAQ (Preguntas Frecuentes (FAQ))</li></ul>',27)])])}const h=a(o,[["render",s]]);export{p as __pageData,h as default};
